        --gold-base: #cca565;
        --gold-dark: #8c6733;
        --cyan-glow: #38ebff;
        --text-gold: #e2c892;
      }

      @keyframes spin { 100% { transform: rotate(360deg); } }
      @keyframes spinReverse { 100% { transform: rotate(-360deg); } }
      @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
      @keyframes float { 
          0%, 100% { transform: translateY(0) scale(1); } 
          50% { transform: translateY(-10px) scale(1.02); } 
      }
      @keyframes trainWarp { 
          0% { transform: translate(-120px, 120px) scale(0.5); opacity: 0; filter: drop-shadow(0 0 10px var(--cyan-glow)); } 
          30% { opacity: 1; }
          70% { opacity: 1; }
          100% { transform: translate(120px, -120px) scale(1.5); opacity: 0; filter: drop-shadow(0 0 30px var(--cyan-glow)); } 
      }
      @keyframes twinkle {
          0%, 100% { opacity: 0.2; }
          50% { opacity: 0.8; }
      }

      body {
        background: radial-gradient(circle at center, var(--space-blue) 0%, var(--space-dark) 100%);
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
        -webkit-font-smoothing: antialiased;
        margin: 0;
        height: 100vh;
        display: flex;
        justify-content: center;
        align-items: center;
        overflow: hidden;
      }

      /* 简易星空点缀 */
      .stars {
        position: absolute;
        top: 0; left: 0; width: 100%; height: 100%;
        background-image: 
          radial-gradient(1.5px 1.5px at 20px 30px, #fff, rgba(0,0,0,0)),
          radial-gradient(2px 2px at 150px 70px, var(--gold-light), rgba(0,0,0,0)),
          radial-gradient(1px 1px at 50px 160px, #fff, rgba(0,0,0,0)),
          radial-gradient(2px 2px at 290px 40px, var(--cyan-glow), rgba(0,0,0,0)),
          radial-gradient(1.5px 1.5px at 330px 180px, var(--gold-base), rgba(0,0,0,0)),
          radial-gradient(2px 2px at 160px 220px, #fff, rgba(0,0,0,0));
        background-repeat: repeat;
        background-size: 400px 400px;
        animation: twinkle 4s infinite;
        z-index: 0;
      }

      /* 星轨罗盘外层容器 */
      .compass-wrapper {
        position: relative;
        width: 90vw;
        max-width: 420px;
        aspect-ratio: 1 / 1;
        border-radius: 50%;
        animation: float 6s ease-in-out infinite;
        z-index: 10;
        display: flex;
        justify-content: center;
        align-items: center;
        /* 外层金属质感边框 */
        background: conic-gradient(from 0deg, 
            var(--gold-dark), var(--gold-light), var(--gold-dark), 
            var(--gold-light), var(--gold-dark));
        padding: 12px;
        box-shadow: 
            0 0 40px rgba(140, 103, 51, 0.4),
            inset 0 0 15px rgba(0,0,0,0.8);
      }

      /* 旋转的星轨刻度层 (明暗金交错) */
      .compass-ring-outer {
        position: absolute;
        top: 6px; left: 6px; right: 6px; bottom: 6px;
        border-radius: 50%;
        border: 2px dashed var(--gold-light);
        opacity: 0.6;
        animation: spin 40s linear infinite;
        pointer-events: none;
      }

      .compass-ring-inner {
        position: absolute;
        top: 22px; left: 22px; right: 22px; bottom: 22px;
        border-radius: 50%;
        border: 4px double var(--gold-base);
        border-left-color: transparent;
        border-right-color: transparent;
        animation: spinReverse 25s linear infinite;
        pointer-events: none;
      }

      /* 罗盘内部视窗 (深空背景) */
      .compass-glass {
        position: relative;
        width: 100%;
        height: 100%;
        border-radius: 50%;
        background: radial-gradient(circle at center, rgba(17,29,51,0.9) 0%, rgba(9,14,23,0.98) 100%);
        border: 3px solid var(--gold-dark);
        box-shadow: inset 0 0 50px rgba(56, 235, 255, 0.15); /* 内部幽蓝光晕 */
        overflow: hidden;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
      }

      /* ----- 状态1：开场动画屏 ----- */
      #splash-screen {
        position: absolute;
        width: 100%;
        height: 100%;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        transition: opacity 0.8s ease-in-out;
        z-index: 1000;
      }

      /* 贯穿罗盘的跃迁光束 */
      .warp-beam {
        position: absolute;
        width: 150%;
        height: 2px;
        background: linear-gradient(90deg, transparent, var(--cyan-glow), transparent);
        transform: rotate(-45deg);
        box-shadow: 0 0 15px var(--cyan-glow);
        opacity: 0.8;
      }

      .train-container {
        font-size: 4rem;
        color: var(--gold-light);
        animation: trainWarp 3.5s cubic-bezier(0.25, 0.1, 0.25, 1) forwards;
        z-index: 2;
        transform: rotate(-45deg);
      }

      .splash-text {
        position: absolute;
        bottom: 25%;
        font-size: 0.9rem;
        letter-spacing: 6px;
        color: var(--text-gold);
        font-weight: 300;
        animation: fadeIn 1.5s ease-in-out;
        text-shadow: 0 0 10px rgba(226, 200, 146, 0.5);
      }

      /* ----- 状态2：跃迁搜索屏 ----- */
      #home-screen {
         width: 100%;
         height: 100%;
         display: none; /* 初始隐藏 */
         flex-direction: column;
         justify-content: center;
         align-items: center;
         opacity: 0;
         animation: fadeIn 1s ease-out forwards;
      }

      .search-box-wrapper {
        width: 80%;
        display: flex;
        flex-direction: column;
        align-items: center;
      }

      .search-logo {
        color: var(--gold-light);
        font-size: 1.6rem;
        letter-spacing: 4px;
        margin-bottom: 30px;
        text-shadow: 0 2px 10px rgba(204, 165, 101, 0.4);
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 8px;
      }
      
      .search-logo i {
        font-size: 2rem;
        color: var(--cyan-glow);
        text-shadow: 0 0 15px rgba(56, 235, 255, 0.6);
      }

      .search-input-container {
        position: relative;
        width: 100%;
        display: flex;
        align-items: center;
        background: rgba(0, 0, 0, 0.3);
        border: 1px solid var(--gold-dark);
        border-radius: 20px;
        padding: 4px 12px;
        box-shadow: inset 0 0 10px rgba(0,0,0,0.5);
        transition: all 0.3s ease;
      }

      .search-input-container:focus-within {
        border-color: var(--gold-light);
        box-shadow: 0 0 15px rgba(204, 165, 101, 0.3), inset 0 0 10px rgba(56, 235, 255, 0.1);
      }

      .search-icon {
        color: var(--gold-base);
        font-size: 1rem;
        margin-right: 10px;
      }

      .search-input {
        flex-grow: 1;
        width: 100%;
        border: none;
        background: transparent;
        padding: 10px 0;
        font-size: 0.95rem;
        color: var(--cyan-glow);
        outline: none;
        letter-spacing: 1px;
      }

      .search-input::placeholder {
        color: rgba(226, 200, 146, 0.5);
        font-size: 0.85rem;
      }

      .search-button {
        background: linear-gradient(135deg, var(--gold-base), var(--gold-dark));
        color: var(--space-dark);
        border: none;
        border-radius: 15px;
        padding: 6px 14px;
        font-weight: bold;
        font-size: 0.9rem;
        cursor: pointer;
        transition: transform 0.1s, filter 0.2s;
        box-shadow: 0 2px 8px rgba(0,0,0,0.4);
      }

      .search-button:active {
        transform: scale(0.95);
        filter: brightness(1.2);
      }
    </style>
</head>
<body>
    <div class="stars"></div>

    <div class="compass-wrapper">
        <div class="compass-ring-outer"></div>
        <div class="compass-ring-inner"></div>
        
        <div class="compass-glass">
            
            <div id="splash-screen">
                <div class="warp-beam"></div>
                <div class="train-container">
                    <i class="fa-solid fa-train"></i>
                </div>
                <div class="splash-text">星海漫游</div>
            </div>

            <div id="home-screen">
              <div class="search-box-wrapper">
                  <div class="search-logo">
                      <i class="fa-solid fa-compass"></i>
                      <span>星轨导航</span>
                  </div>
                  <div class="search-input-container">
                      <i class="fa-solid fa-crosshairs search-icon"></i>
                      <input type="text" id="search-input" class="search-input" placeholder="寻找跃迁坐标..." autocomplete="off">
                      <button id="search-btn" class="search-button">导航</button>
                  </div>
              </div>
            </div>

        </div>
    </div>

    <script>
    document.addEventListener('DOMContentLoaded', () => {
        const splash = document.getElementById('splash-screen');
        const home = document.getElementById('home-screen');
        const searchBtn = document.getElementById('search-btn');
        const searchInput = document.getElementById('search-input');

        // 动画过渡逻辑：匹配列车跃迁时间(3.5s)，然后淡出显示主屏
        setTimeout(() => {
            splash.style.opacity = '0';
            setTimeout(() => {
                splash.style.display = 'none';
                home.style.display = 'flex';
            }, 800); // 等待淡出动画结束
        }, 3200);

        // 发送指令函数
        function sendCommand(messageText) {
            const command = `/send "${messageText.replace(/"/g, '\\"')}" | /trigger await=true`;

            if (typeof triggerSlash === 'function') {
                try {
                    triggerSlash(command);
                } catch (e) {
                    console.error("指令发送失败:", e);
                    alert(`坐标确认失败，请手动复制指令：\n${messageText}`);
                }
            } else {
                console.log("模拟发送指令:", messageText);
            }
        }

        // 绑定搜索事件
        const executeSearch = () => {
            const keyword = searchInput.value.trim();
            if(keyword !== '') {
                sendCommand(`搜索：${keyword}`);
                searchInput.value = ''; // 清空输入框
            }
        };

        searchBtn.onclick = executeSearch;
        
        // 支持回车搜索
        searchInput.addEventListener('keypress', function (e) {
            if (e.key === 'Enter') {
                executeSearch();
            }
        });
    });
    </script>
</body>
</html>
