                appData.recTags = recMatch[1].trim().split('\n')
                    .map(l => l.replace(/^- /, '').trim())
                    .filter(l => l);
            }

            // 解析星域
            const domainRegex = /\[星域\]([\s\S]*?)\[\/星域\]/g;
            let dm;
            while ((dm = domainRegex.exec(text)) !== null) {
                const dc = dm[1];
                const domain = { targets: [] };
                domain.name = dc.match(/name:\s*(.*)/)?.[1].trim() || '未知星域';
                domain.stars = parseFloat(dc.match(/stars:\s*(.*)/)?.[1] || 0);
                domain.domaintags = parseBlockList(dc, 'domaintags');

                // 解析开拓目标
                const targetRx = /\[开拓目标\]([\s\S]*?)\[\/开拓目标\]/g;
                let tm;
                while ((tm = targetRx.exec(dc)) !== null) {
                    const tc = `\n${tm[1]}`;
                    const target = {};
                    target.name        = tc.match(/\nname:\s*(.*)/)?.[1].trim() || '未知目标';
                    target.cost        = tc.match(/\ncost:\s*(.*)/)?.[1].trim() || '🔮未知';
                    target.quality     = tc.match(/\nquality:\s*(.*)/)?.[1].trim() || 'C';
                    target.penetration = tc.match(/\npenetration:\s*(.*)/)?.[1].trim() || '未知';
                    target.stars       = parseFloat(tc.match(/\nstars:\s*(.*)/)?.[1] || 0);

                    target.images = [];
                    for (let i = 1; i <= 3; i++) {
                        const ir = new RegExp(`\\nimage${i}:\\s*([\\s\\S]*?)(?=\\nimage${i+1}:|\\ndescription:)`);
                        const im = tc.match(ir); if (im) target.images.push(im[1].trim());
                    }

                    target.description = tc.match(/\ndescription:\s*([\s\S]*?)(?=\nexploration_content:|\nMarch7_reviews:|\nstellar_reviews:)/)?.[1].trim() || '';
                    target.tags        = parseBlockList(tc, 'tags');
                    target.content     = parseBlockList(tc, 'exploration_content');
                    // 独立解析三月七针对目标的专属评价
                    target.m7_reviews  = parseBlockList(tc, 'March7_reviews');
                    target.reviews     = parseBlockList(tc, 'stellar_reviews');
                    domain.targets.push(target);
                }
                appData.domains.push(domain);
            }
        }

        function parseBlockList(content, key) {
            const lines = content.split('\n'); const result = []; let inList = false;
            for (const line of lines) {
                if (line.trim().startsWith(key + ':')) { inList = true; continue; }
                if (inList) {
                    const t = line.trim();
                    if (t.startsWith('- ')) {
                        let c = t.substring(2).trim();
                        // 移除评语的外部引号
                        if ((key === 'stellar_reviews' || key === 'March7_reviews') && c.startsWith('"') && c.endsWith('"')) c = c.slice(1, -1);
                        result.push(c);
                    } else if (t !== '' && /^\w+:/.test(t)) inList = false;
                }
            }
            return result;
        }

        function renderStars(r) {
            let h = '';
            for (let i = 1; i <= 5; i++) {
                if (i <= r) h += '<i class="fa-solid fa-star"></i>';
                else if (i - r < 1) h += '<i class="fa-solid fa-star-half-stroke"></i>';
                else h += '<i class="fa-regular fa-star"></i>';
            }
            return `${r.toFixed(1)} <span style="font-size:0.8rem">${h}</span>`;
        }

        function extractEmoji(str) {
            const m = (str || '').match(EMOJI_RX); return m ? m[0] : null;
        }

        function getQualityClass(q) {
            const lq = (q || '').toLowerCase();
            if (lq.includes('s')) return 'sss';
            return lq;
        }

        // 复用Review渲染组件
        function renderReviewItem(r, isM7 = false) {
            let rText = r.trim();
            let rName = isM7 ? '三月七' : '匿名观测者'; 
            let rEmoji = isM7 ? '📷' : '📡'; 
            let rIdentity = isM7 ? '领航员' : '';

            const ci = rText.search(/[:：]/);
            if (ci > 0 && ci < 45) {
                let np = rText.substring(0, ci).trim();
                rText = rText.substring(ci + 1).replace(/^["']|["']$/g, '').trim();
                const em = np.match(EMOJI_RX); if (em) { rEmoji = em[0]; np = np.replace(rEmoji, '').trim(); }
                const bm = [...np.matchAll(/\[([^\]]+)\]|【([^】]+)】/g)];
                if (bm.length >= 2) { rIdentity = bm[0][1]||bm[0][2]; rName = bm[1][1]||bm[1][2]; }
                else if (bm.length === 1) {
                    const after = np.substring(bm[0].index + bm[0][0].length).trim();
                    if (after) { rIdentity = bm[0][1]||bm[0][2]; rName = after; }
                    else rName = bm[0][1]||bm[0][2];
                } else rName = np.replace(/[()（）\[\]【】]/g, '').trim();
            }

            const idH = rIdentity ? `<span class="review-id-tag">${rIdentity}</span>` : '';
            return `<div class="review">
                <div class="review-avatar">${rEmoji}</div>
                <div class="review-content">
                    <div class="review-user">${idH} <span>${rName}</span></div>
                    <div class="review-text">${rText}</div>
                </div></div>`;
        }

        // ─── Rendering Views ──────────────────────────────────────
        function renderDomains() {
            contentArea.innerHTML = '';
            currentView = 'domains'; currentDomIndex = -1; currentTgtIndex = -1;
            setNavEmoji(DEFAULT_ICON, null);
            updateBackBtn();

            // M7 Comment (开场寄语)
            if (appData.m7comment) {
                const m7box = document.createElement('div');
                m7box.className = 'm7-comment-box';
                m7box.innerHTML = `
                    <div class="m7-comment-header"><i class="fa-solid fa-camera-retro"></i> 领航员寄语</div>
                    <div class="m7-comment-text">"${appData.m7comment}"</div>
                `;
                contentArea.appendChild(m7box);
            }

            // Recommended Tags
            if (appData.recTags.length > 0) {
                const rc = document.createElement('div');
                rc.className = 'recommended-tags-container';
                rc.innerHTML = `<div class="title"><i class="fa-solid fa-route"></i> 热门跃迁坐标</div>
                  <div class="recommended-tags">${appData.recTags.map(t => `<div class="rec-tag">${t}</div>`).join('')}</div>`;
                contentArea.appendChild(rc);
                rc.querySelectorAll('.rec-tag').forEach(el => 
                    el.onclick = () => sendSillyTavernCommand({ send: `搜索${el.textContent}` }));
            }

            // Domains List
            appData.domains.forEach((domain, i) => {
                const card = document.createElement('div');
                card.className = 'domain-card';
                card.innerHTML = `
                    <div class="card-header">
                        <h3 class="card-title">${domain.name}</h3>
                        <div class="card-stars">${renderStars(domain.stars)}</div>
                    </div>
                    <div class="card-tags">${domain.domaintags.map(t => `<span class="tag">${t}</span>`).join('')}</div>
                    <div style="margin-top:14px; font-size:0.9rem; color:var(--text-secondary);"><i class="fa-solid fa-satellite-dish"></i> 探测到 ${domain.targets.length} 个目标</div>
                `;
                card.onclick = () => renderTargets(i);
                contentArea.appendChild(card);
            });
        }

        function renderTargets(domIndex) {
            currentDomIndex = domIndex;
            currentView = 'targets'; currentTgtIndex = -1;

            const domName = appData.domains[domIndex].name;
            const domEmoji = extractEmoji(domName);
            setNavEmoji(domEmoji ? domEmoji : '<i class="fa-solid fa-planet-ringed"></i>', null);
            updateBackBtn();

            contentArea.innerHTML = `<div style="font-size:1rem; color:var(--app-primary-light); margin-bottom:16px; font-weight:bold;">
                <i class="fa-solid fa-network-wired"></i> 当前星域：${domName}
            </div>`;

            appData.domains[domIndex].targets.forEach((tgt, i) => {
                const card = document.createElement('div');
                card.className = 'target-card';
                card.innerHTML = `
                    <div class="card-header">
                        <h3 class="card-title">${tgt.name}</h3>
                        <div class="card-stars">${renderStars(tgt.stars)}</div>
                    </div>
                    <div class="card-tags">${tgt.tags.map(t => `<span class="tag">${t}</span>`).join('')}</div>
                    <div class="target-meta">
                        <div class="target-meta-item"><span class="quality-badge ${getQualityClass(tgt.quality)}">${tgt.quality}级</span></div>
                        <div class="target-meta-item" style="color:var(--price-color); font-weight:bold; font-size: 0.95rem;">${tgt.cost}</div>
                    </div>
                `;
                card.onclick = () => renderDetails(domIndex, i);
                contentArea.appendChild(card);
            });
        }

        function renderDetails(domIndex, tgtIndex) {
            currentDomIndex = domIndex; currentTgtIndex = tgtIndex;
            currentView = 'details';
            const tgt = appData.domains[domIndex].targets[tgtIndex];

            const tgtEmoji = extractEmoji([tgt.name, ...tgt.tags, tgt.description].join(' ')) || '✨';
            const orderFn = () => {
                const remarks = prompt(`锁定开拓目标 "${tgt.name}"。添加折跃备注（可留空）：`, '');
                if (remarks === null) return;
                sendSillyTavernCommand({ send: `向星穹列车提交了开拓目标 "${tgt.name}" 的折跃申请。\n备注：${remarks || '无'}` });
            };
            setNavEmoji(tgtEmoji, orderFn);
            updateBackBtn();

            // 渲染三月七专属特评栏目
            const renderedM7Reviews = (tgt.m7_reviews || []).map(r => renderReviewItem(r, true)).join('');
            const m7SectionHtml = renderedM7Reviews ? `
                <div class="detail-section m7-special-section">
                    <h4 class="section-title"><i class="fa-solid fa-camera-retro"></i> 领航员特评</h4>
                    <div class="reviews">${renderedM7Reviews}</div>
                </div>
            ` : '';

            // 渲染星际回响（其他人评价）
            const renderedReviews = (tgt.reviews || []).map(r => renderReviewItem(r, false)).join('');

            contentArea.innerHTML = `
                <div class="detail-view">
                    <div class="detail-section" style="padding-bottom:14px;">
                        <div class="detail-header">
                            <h3 class="detail-title">${tgt.name}</h3>
                            <div class="quality-badge ${getQualityClass(tgt.quality)}" style="font-size:0.95rem;">${tgt.quality}级</div>
                        </div>
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:10px;">
                            <div class="card-stars">${renderStars(tgt.stars)}</div>
                            <div style="color:var(--price-color); font-weight:800; font-size:1.05rem;">${tgt.cost}</div>
                        </div>
                        <div style="font-size:0.9rem; color:var(--text-secondary); margin-top:10px;">${tgt.penetration}</div>
                        <div class="card-tags" style="margin-top:16px;">${tgt.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div>
                    </div>

                    <div class="image-carousel">
                        <div class="carousel-images-container">
                            ${tgt.images.map((img,i)=>`<div class="carousel-image-description"><strong><i class="fa-brands fa-galactic-senate"></i> 绝密全息影像 (${i+1}/${tgt.images.length})</strong>${img}</div>`).join('')}
                        </div>
                        <div class="dots-wrapper"><div class="image-dots"></div></div>
                    </div>

                    <div class="detail-section">
                        <h4 class="section-title"><i class="fa-solid fa-book-journal-whills"></i> 目标情报</h4>
                        <p class="detail-description">${tgt.description}</p>
                    </div>

                    <div class="detail-section">
                        <h4 class="section-title"><i class="fa-solid fa-map-location-dot"></i> 特色开拓内容</h4>
                        <div class="detail-content"><ul>${tgt.content.map(c=>`<li>${c}</li>`).join('')}</ul></div>
                    </div>

                    <!-- 三月七特评单独一栏 -->
                    ${m7SectionHtml}

                    <div class="detail-section" style="margin-bottom:6px; border:none; background:transparent; padding:0; box-shadow:none;">
                        <h4 class="section-title" style="color:var(--text-secondary); font-size:0.95rem; border:none;"><i class="fa-solid fa-comments"></i> 星际回响 (${tgt.reviews.length})</h4>
                        <div class="reviews">${renderedReviews}</div>
                    </div>
                </div>`;

            // Carousel Init
            let cur = 0;
            const imgsC = contentArea.querySelector('.carousel-images-container');
            const imgs  = contentArea.querySelectorAll('.carousel-image-description');
            const dotsC = contentArea.querySelector('.image-dots');
            if (imgs.length > 1) {
                imgs.forEach((_, i) => {
                    const d = document.createElement('span');
                    d.className = i === 0 ? 'dot active' : 'dot';
                    d.onclick = () => show(i); dotsC.appendChild(d);
                });
                const dots = dotsC.querySelectorAll('.dot');
                function show(idx) {
                    dots[cur].classList.remove('active');
                    cur = (idx + imgs.length) % imgs.length;
                    imgsC.style.transform = `translateX(-${cur*100}%)`;
                    dots[cur].classList.add('active');
                }
                let sx = 0;
                imgsC.addEventListener('touchstart', e => { sx = e.changedTouches[0].screenX; }, {passive:true});
                imgsC.addEventListener('touchend',   e => {
                    const dx = e.changedTouches[0].screenX - sx;
                    if (dx < -40) show(cur+1); if (dx > 40) show(cur-1);
                }, {passive:true});
            }
        }

        // Initialize
        const rawData = dataContainer.textContent.trim();
        if (rawData && rawData.length > 10) { 
            parseData(rawData); renderDomains(); 
        } else { 
            contentArea.innerHTML = '<div style="text-align:center;color:var(--text-secondary);padding:80px 20px;"><i class="fa-solid fa-satellite" style="font-size:3rem;margin-bottom:18px;opacity:.5;color:var(--app-primary);"></i><br><span style="font-size:1.1rem">正在接收星穹列车导航数据...</span><br><br>请重新发送指令刷新罗盘。</div>';
        }
    });
    </script>
</body>
</html>
